function transform (message, context) {
  const payload = message.payload || {};

  const trim = (value) => {
    if (value === null || typeof value === 'undefined') {
      return '';
    }

    return `${value}`.trim();
  };

  const input = {
    bannerId: trim(context.get('bannerId') || payload.bannerId),
    username: trim(context.get('username') || payload.username),
    personalEmail: trim(context.get('personalEmail') || payload.personalEmail),
    firstName: trim(context.get('firstName') || payload.firstName),
    lastName: trim(context.get('lastName') || payload.lastName)
  };

  let searchMode = '';
  let criteriaObject = null;

  if (input.bannerId) {
    searchMode = 'bannerId';
    criteriaObject = {
      credentials: [
        {
          type: 'bannerId',
          value: input.bannerId
        }
      ]
    };
  } else if (input.username) {
    searchMode = 'username';
    criteriaObject = {
      credentials: [
        {
          type: 'bannerUserName',
          value: input.username
        }
      ]
    };
  } else if (input.personalEmail) {
    searchMode = 'personalEmail';
    criteriaObject = {
      emails: [
        {
          address: input.personalEmail
        }
      ]
    };
  } else if (input.firstName || input.lastName) {
    searchMode = 'name';
    const nameCriteria = {};

    if (input.firstName) {
      nameCriteria.firstName = input.firstName;
    }
    if (input.lastName) {
      nameCriteria.lastName = input.lastName;
    }

    criteriaObject = {
      names: [nameCriteria]
    };
  }

  if (!criteriaObject) {
    throw new Error('One search criterion is required: bannerId, username, personalEmail, or first/last name.');
  }

  return {
    payload: {
      ...payload,
      searchMode,
      criteriaObject,
      criteriaEncoded: encodeURIComponent(JSON.stringify(criteriaObject))
    }
  };
}

function transform(message) {
  const payload = message.payload;
  const payloadArray = Array.isArray(payload) ? payload : null;
  const payloadObject =
    (!payloadArray && payload && typeof payload === 'object') ? payload : {};

  const sourceRows = Array.isArray(payloadObject.person)
    ? payloadObject.person
    : Array.isArray(payloadObject.persons)
      ? payloadObject.persons
      : (payloadArray || []);

  const rows = sourceRows.flatMap((row) =>
    Array.isArray(row?.person) ? row.person : [row]
  );

  const normalize = (person) => {
    const credentials = Array.isArray(person?.credentials) ? person.credentials : [];
    const names = Array.isArray(person?.names) ? person.names : [];
    const emails = Array.isArray(person?.emails) ? person.emails : [];

    const byCredential = (type) => {
      const match = credentials.find((entry) =>
        `${entry?.type || ''}`.toLowerCase() === `${type}`.toLowerCase()
      );
      return match?.value || '';
    };

    const preferredName =
      names.find((entry) =>
        `${entry?.type?.category || ''}`.toLowerCase() === 'favored'
      ) ||
      names.find((entry) =>
        `${entry?.preference || ''}`.toLowerCase() === 'preferred'
      ) ||
      names[0] ||
      {};

    const preferredEmail = emails.find((entry) =>
      `${entry?.preference || ''}`.toLowerCase() === 'primary'
    ) || emails[0] || {};

    const firstName = preferredName.firstName || person?.firstName || '';
    const lastName = preferredName.lastName || person?.lastName || '';
    const bannerId = byCredential('bannerId');
    const username = byCredential('bannerUserName');

    return {
      id: person?.id || '',
      studentId: bannerId || person?.id || '',
      bannerId,
      username,
      firstName,
      lastName,
      displayName: `${firstName} ${lastName}`.trim() || person?.id || 'Unknown',
      email: preferredEmail.address || person?.email || person?.emailAddress || ''
    };
  };

  return {
    payload: rows
      .filter((row) => row && row.id)
      .map(normalize)
  };
}
